next_equipped_weapons_delete.SQL:
CREATE TRIGGER next_equipped_weapons_delete INSTEAD OF DELETE ON local_equipped_weapons BEGIN
    DELETE FROM local_weapon_assets WHERE instance_id=OLD.instance_id AND location=3 AND slot=12;
END

next_fate_exchange_no_delete.SQL:
CREATE TRIGGER next_fate_exchange_no_delete BEFORE DELETE ON local_fate_exchange_purchases BEGIN
    SELECT RAISE(ABORT,'Account exchange receipts are permanent');
END

next_fate_exchange_no_update.SQL:
CREATE TRIGGER next_fate_exchange_no_update BEFORE UPDATE ON local_fate_exchange_purchases BEGIN
    SELECT RAISE(ABORT,'Account exchange receipts are immutable');
END

next_character_receipts_insert.SQL:
CREATE TRIGGER next_character_receipts_insert AFTER INSERT ON local_entry_characters BEGIN
    INSERT INTO local_character_receipts(character_id,receipts_json) VALUES(NEW.id,NEW.receipts_json);
END
